<?php use Sigesp\Core\{Csrf, Flash, View}; $title = 'Acessar o SIGESP'; $flash = Flash::pull(); ?>
<div class="auth-title"><h1>Bem-vindo de volta</h1><p>Informe suas credenciais para acessar o ambiente administrativo.</p></div><?php if ($flash): ?><div class="alert alert--error" role="alert"><?= View::e($flash['message']) ?></div><?php endif; ?><form method="post" action="/login" class="form" data-loading-form><input type="hidden" name="_token" value="<?= Csrf::token() ?>"><label class="field">CPF ou e-mail<input name="identificador" autocomplete="username" required aria-describedby="login-help"><small id="login-help">Use o CPF cadastrado ou seu e-mail institucional.</small></label><label class="field">Senha<span class="password-field"><input name="senha" type="password" autocomplete="current-password" required minlength="8"><button type="button" data-password-toggle>Mostrar</button></span></label><div class="remember-row"><label><input type="checkbox" name="lembrar" value="1"> Lembrar acesso</label><a href="/recuperar-senha">Esqueci minha senha</a></div><button class="button" type="submit">Entrar no SIGESP</button></form>
